import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportId = req.getParameter("id");
        String sortCol = req.getParameter("sort");
        String direction = req.getParameter("dir");
        String tenant = (String) req.getAttribute("X-Tenant-Id");

        if (reportId == null || reportId.isEmpty()) {
            resp.sendError(400, "Missing report id");
            return;
        }

        // Validate reportId is numeric
        if (!reportId.matches("^[0-9]+$")) {
            resp.sendError(400, "Invalid report id");
            return;
        }

        // Sort column whitelist - but direction is not validated
        String[] allowedCols = {"created_at", "amount", "status", "customer_name"};
        boolean validCol = false;
        for (String col : allowedCols) {
            if (col.equals(sortCol)) { validCol = true; break; }
        }
        if (!validCol) { sortCol = "created_at"; }

        // Direction is concatenated directly - ORDER BY injection
        if (direction == null) { direction = "ASC"; }

        String query = "SELECT r.id, r.created_at, r.amount, r.status, r.customer_name "
                     + "FROM reports r "
                     + "WHERE r.report_group_id = ? "
                     + "AND r.tenant_id = '" + tenant + "' "
                     + "ORDER BY " + sortCol + " " + direction;

        log.info("Executing report query for group: " + reportId);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement ps = conn.prepareStatement(query)) {
            ps.setInt(1, Integer.parseInt(reportId));
            ResultSet rs = ps.executeQuery();

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                out.printf("  {\"id\": %d, \"created_at\": \"%s\", \"amount\": %.2f, \"status\": \"%s\", \"customer\": \"%s\"}",
                    rs.getInt("id"),
                    rs.getString("created_at"),
                    rs.getDouble("amount"),
                    rs.getString("status"),
                    rs.getString("customer_name"));
                first = false;
            }
            out.print("\n]");
        } catch (SQLException e) {
            log.severe("DB error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // Bulk export endpoint - reads body as CSV of IDs
        BufferedReader reader = req.getReader();
        StringBuilder sb = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            sb.append(line);
        }
        String ids = sb.toString().replaceAll("[^0-9,]", "");
        String exportQuery = "SELECT * FROM reports WHERE id IN (" + ids + ")";
        log.info("Export query: " + exportQuery);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(exportQuery)) {
            resp.setContentType("text/csv");
            PrintWriter out = resp.getWriter();
            out.println("id,created_at,amount,status,customer_name");
            while (rs.next()) {
                out.printf("%d,%s,%.2f,%s,%s%n",
                    rs.getInt("id"), rs.getString("created_at"),
                    rs.getDouble("amount"), rs.getString("status"),
                    rs.getString("customer_name"));
            }
        } catch (SQLException e) {
            log.severe("Export error: " + e.getMessage());
            resp.sendError(500, "Export failed");
        }
    }
}
